sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:Fame_(1936_film) dbr:It%27s_All_About_Love }

  # director (prefer dbp:director)
  { ?film dbp:director ?director }
  UNION
  { ?film dbo:director ?director .
    FILTER NOT EXISTS { ?film dbp:director ?anyDir } }

  # director's birth date (prefer dbp:birthDate)
  OPTIONAL {
    { ?director dbp:birthDate ?birthDate }
    UNION
    { ?director dbo:birthDate ?birthDate .
      FILTER NOT EXISTS { ?director dbp:birthDate ?anyBD } }
  }
}
LIMIT 100

